package lc3983

import (
	"reflect"
	"testing"
)

func TestCanMakeSubsequence(t *testing.T) {
	tests := []struct {
		name string
		s    string
		t    string
		want bool
	}{

		{
			name: "example 1",
			s:    "cat",
			t:    "chat",
			want: true,
		},

		{
			name: "example 2",
			s:    "plane",
			t:    "apple",
			want: false,
		},

		{
			name: "example 3",
			s:    "az",
			t:    "bzy",
			want: true,
		},

		{
			name: "example 4",
			s:    "ws",
			t:    "xwxt",
			want: true,
		},

		{
			name: "example 5",
			s:    "qo",
			t:    "npnmq",
			want: false,
		},

		{
			name: "example 6",
			s:    "zz",
			t:    "zyayb",
			want: true,
		},

		{
			name: "example 7",
			s:    "yz",
			t:    "zbaa",
			want: false,
		},

		{
			name: "example 8",
			s:    "bbb",
			t:    "yab",
			want: false,
		},

		{
			name: "example 9",
			s:    "mn",
			t:    "mp",
			want: true,
		},

		{
			name: "example 10",
			s:    "",
			t:    "",
			want: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out := canMakeSubsequence(tt.s, tt.t)

			if !reflect.DeepEqual(out, tt.want) {
				t.Fatalf("got %v want %v", out, tt.want)
			}
		})
	}
}
